import os
import time
import json
from typing import Any, Dict, Optional

import assemblyai as aai


def transcribe_with_diarization(
    audio_source: str,
    speaker_labels: bool = True,
    wait: bool = True,
    poll_interval: float = 5.0,
    timeout: Optional[float] = None,
) -> Dict[str, Any]:
    api_key = os.getenv("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("ASSEMBLYAI_API_KEY is not set")

    aai.settings.api_key = api_key

    transcript = aai.Transcript(
        audio_source,
        speaker_labels=speaker_labels,
    )

    transcript = transcript.create()

    if wait:
        start = time.time()
        while transcript.status not in ("completed", "error"):
            if timeout is not None and (time.time() - start) > timeout:
                raise TimeoutError("Transcription timed out")
            time.sleep(poll_interval)
            transcript = aai.Transcript.get(transcript.id)

    if transcript.status == "error":
        raise RuntimeError(getattr(transcript, "error", "AssemblyAI transcription failed"))

    utterances = []
    if getattr(transcript, "utterances", None):
        for u in transcript.utterances:
            utterances.append(
                {
                    "speaker": getattr(u, "speaker", None),
                    "start": getattr(u, "start", None),
                    "end": getattr(u, "end", None),
                    "text": getattr(u, "text", None),
                }
            )

    return {
        "id": transcript.id,
        "status": transcript.status,
        "text": getattr(transcript, "text", None),
        "utterances": utterances,
        "raw": {
            "speaker_labels": speaker_labels,
        },
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <audio_file_or_url>")

    result = transcribe_with_diarization(sys.argv[1])
    print(json.dumps(result, indent=2, ensure_ascii=False))
